import sys

def can_be_expressed_as_sum_of_two_vectors():
    # Read input
    grid = [list(map(int, input().split())) for _ in range(3)]

    # Check if the grid can be expressed as a sum of two vectors
    for i in range(1, 3):
        if any(grid[i][j] != grid[0][j] for j in range(3)):
            return "No"
    for j in range(1, 3):
        if any(grid[i][j] != grid[i][0] for i in range(3)):
            return "No"

    return "Yes"

